import orders from './orders.json' with { type: 'json' };

const TOOL_NAME = 'order_status';
const ALLOWED_FIELDS = new Set(['order_id', 'include_history']);

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description:
        'Look up the current status of an order by id. When include_history is true, also returns the chronological state history.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: {
            type: 'string',
            description: 'The id of the order to look up.'
          },
          include_history: {
            type: 'boolean',
            description:
              'Whether to include the chronological state history of the order.',
            default: false
          }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

function validateArgs(args) {
  const a = args && typeof args === 'object' ? args : {};

  for (const key of Object.keys(a)) {
    if (!ALLOWED_FIELDS.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (typeof a.order_id !== 'string' || a.order_id.length === 0) {
    throw new Error('Missing or invalid required field: order_id');
  }

  if (a.include_history !== undefined && typeof a.include_history !== 'boolean') {
    throw new Error('Invalid field: include_history must be a boolean');
  }

  return {
    order_id: a.order_id,
    include_history: a.include_history === undefined ? false : a.include_history
  };
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { order_id, include_history } = validateArgs(args);

  const order = orders[order_id];
  if (!order || typeof order !== 'object') {
    throw new Error(`Order not found: ${order_id}`);
  }

  const lines = [`Order ${order_id} status: ${order.status}`];

  if (include_history) {
    const history = Array.isArray(order.history) ? order.history : [];
    lines.push(`History: ${history.join(' -> ')}`);
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }]
  };
}

